import { Component } from '@angular/core';

@Component({
  selector: 'app-home',
  templateUrl: './home.component.html',
  styleUrls: ['./home.component.css']
})
export class HomeComponent {
  popupAberto = false;
  cotacao = {
    nome: '',
    email: '',
    tipo: ''
  };

  constructor() { }

  // ngOnInit não utilizado

  abrirCotacao() {
    this.popupAberto = true;
  }

  fecharCotacao() {
    this.popupAberto = false;
    this.cotacao = { nome: '', email: '', tipo: '' };
  }

  enviarCotacao() {
    // Aqui você pode integrar com backend ou exibir mensagem de sucesso
    alert('Cotação enviada com sucesso!');
    this.fecharCotacao();
  }
}
<nav class="navbar navbar-expand-lg navbar-dark bg-primary shadow-sm mb-0 py-0" style="min-height:64px;font-family:Arial,Helvetica,sans-serif;">
  <div class="container-fluid">
    <a class="navbar-brand fw-bold text-light d-flex align-items-center" style="font-size:1.5rem;letter-spacing:1px;" href="#">
  <img src="assets/logo-prover.svg" alt="Prover Seguros" style="height:38px;vertical-align:middle;margin-right:12px;">
    </a>
    <button class="navbar-toggler" type="button" data-bs-toggle="collapse" data-bs-target="#navbarNav" aria-controls="navbarNav" aria-expanded="false" aria-label="Toggle navigation">
      <span class="navbar-toggler-icon"></span>
    </button>
    <div class="collapse navbar-collapse" id="navbarNav">
      <ul class="navbar-nav ms-auto align-items-center">
        <li class="nav-item mx-1">
          <a class="nav-link text-light fw-semibold" aria-current="page" href="#">Início</a>
        </li>
        <li class="nav-item mx-1">
          <a class="nav-link text-light fw-semibold" href="#">Sobre</a>
        </li>
        <li class="nav-item mx-1">
          <a class="nav-link text-light fw-semibold" href="#">Produtos</a>
        </li>
        <li class="nav-item mx-1">
          <a class="nav-link text-light fw-semibold" href="#">Contato</a>
        </li>
        <li class="nav-item mx-2">
          <button class="btn btn-outline-light px-3 py-1 fw-semibold border-2" style="border-radius:6px;" routerLink="/login">Área Administrativa</button>
        </li>
      </ul>
    </div>
  </div>
</nav>
<section class="hero bg-white py-5 border-bottom" style="background:linear-gradient(90deg,#f8fafc 60%,#e3eaf3 100%);font-family:Arial,Helvetica,sans-serif;">
  <div class="container">
    <div class="row align-items-center">
      <div class="col-md-7">
        <h1 class="display-5 fw-semibold text-dark mb-3" style="letter-spacing:0.5px;">Soluções em Seguros Corporativos e Pessoais</h1>
        <p class="lead text-secondary mb-4" style="font-size:1.18rem;max-width:520px;">Consultoria especializada, atendimento personalizado e tradição em proteger empresas, famílias e patrimônios. Segurança, confiança e ética para o seu futuro.</p>
        <button class="btn btn-outline-secondary btn-lg px-4 fw-semibold shadow-sm" style="border-radius:6px;letter-spacing:0.5px;" routerLink="/cotacao">Solicitar Cotação</button>
      </div>
    </div>
  </div>
</section>
